import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel source
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void conv1d_fp16_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int batch,
    int in_c,
    int out_c,
    int length_in,
    int kernel_size,
    int stride,
    int dilation,
    int length_out)
{
    int b  = blockIdx.x;                     // batch index
    int oc = blockIdx.y;                     // out channel index
    int lo = threadIdx.x + blockIdx.z * blockDim.x; // output length index

    if (lo >= length_out) return;

    float acc = 0.0f;

    for (int ic = 0; ic < in_c; ++ic) {
        for (int k = 0; k < kernel_size; ++k) {
            int in_idx = lo * stride + k * dilation;
            int input_offset  = ((b * in_c + ic) * length_in) + in_idx;
            int weight_offset = ((oc * in_c + ic) * kernel_size) + k;
            acc += __half2float(input[input_offset]) *
                   __half2float(weight[weight_offset]);
        }
    }

    if (bias != nullptr) {
        acc += __half2float(bias[oc]);
    }

    int out_offset = ((b * out_c + oc) * length_out) + lo;
    output[out_offset] = __float2half(acc);
}

torch::Tensor conv1d_fp16(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int dilation)
{
    const int batch      = input.size(0);
    const int in_c       = input.size(1);
    const int length_in  = input.size(2);
    const int out_c      = weight.size(0);
    const int kernel_sz  = weight.size(2);

    const int length_out = (length_in - dilation * (kernel_sz - 1) - 1) / stride + 1;

    auto output = torch::empty({batch, out_c, length_out}, input.options());

    const int threads = 256;
    dim3 block(threads);
    dim3 grid(batch, out_c, (length_out + threads - 1) / threads);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "conv1d_fp16_kernel", ([&] {
        conv1d_fp16_kernel<<<grid, block>>>(
            reinterpret_cast<const __half*>(input.data_ptr()),
            reinterpret_cast<const __half*>(weight.data_ptr()),
            bias.defined() ? reinterpret_cast<const __half*>(bias.data_ptr()) : nullptr,
            reinterpret_cast<__half*>(output.data_ptr()),
            batch,
            in_c,
            out_c,
            length_in,
            kernel_sz,
            stride,
            dilation,
            length_out);
    }));

    cudaDeviceSynchronize();
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv1d_fp16", &conv1d_fp16, "FP16 Conv1d forward (CUDA)");
}
'''

# Compile the extension
conv1d_ext = load_inline(
    name='conv1d_fp16_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['conv1d_fp16'],
    verbose=False,
)

# ----------------------------------------------------------------------
# Autograd Function (only forward)
# ----------------------------------------------------------------------
class Conv1dFp16Function(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, weight, bias, stride, dilation):
        return conv1d_ext.conv1d_fp16(input, weight, bias, stride, dilation)

    @staticmethod
    def backward(ctx, grad_output):
        raise NotImplementedError("Backward pass is not implemented for the custom Conv1d FP16 kernel.")

# ----------------------------------------------------------------------
# Model definition (drop‑in replacement for the reference Model)
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Custom 1D convolution using an FP16 CUDA kernel.
    Mirrors the interface of the reference Model.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 dilation: int = 1,
                 bias: bool = False):
        super().__init__()
        self.stride = stride
        self.dilation = dilation
        self.kernel_size = kernel_size

        # weight: (out_channels, in_channels, kernel_size) in FP16
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size, dtype=torch.float16)
        )
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(
                torch.empty(out_channels, dtype=torch.float16)
            )
            fan_in = in_channels * kernel_size
            bound = 1 / math.sqrt(fan_in)
            torch.nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is FP16 on CUDA
        x = x.to(dtype=torch.float16, device='cuda')
        weight = self.weight.to(dtype=torch.float16, device='cuda')
        bias = self.bias.to(dtype=torch.float16, device='cuda') if self.bias is not None else torch.tensor([], dtype=torch.float16, device='cuda')
        return Conv1dFp16Function.apply(x, weight, bias if self.bias is not None else torch.tensor([], dtype=torch.float16, device='cuda'), self.stride, self.dilation)
